using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection to receive HttpClient and ILogger from DI.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(IHttpClientFactory httpFactory, ILogger<JsonPlaceholderTools> logger)
{
    [McpServerTool, Description("Get a post by its ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}", cancellationToken);
        return $"Title: {post!.Title}\n\nBody: {post.Body}";
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<Post[]>(url, cancellationToken);
        return string.Join("\n", posts!.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool(ReadOnly = false), Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = httpFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync("/posts",
            new { title, body, userId }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<Post>(cancellationToken);
        return $"Created post with ID: {created!.Id}";
    }
}

internal record Post
{
    [JsonPropertyName("id")]
    public int Id { get; init; }

    [JsonPropertyName("userId")]
    public int UserId { get; init; }

    [JsonPropertyName("title")]
    public string Title { get; init; } = "";

    [JsonPropertyName("body")]
    public string Body { get; init; } = "";
}

